#!/usr/bin/env python3
from __future__ import annotations
import base64, hashlib, json, os, random, subprocess, sys
from pathlib import Path

MISSION="RS-DEFHS-SYSTEM-IMPLEMENTATION-001"
SEED=20261001
CLASSES=["angry","happy","neutral","sad"]
VB_SHA="87c6c0b33e5ea5c05b2bd2537d29480e4285cf816d4a921a6f1bcb3ef854139b"
VA_SHA="dcee356b0a66cb73c506bb71a6c57962227d6d0474efd3e4d6c404168308f3d1"
MANIFEST_SHA="1e5552d42aec94efae197e7dac95de41cfc96e40336f3e513b9a87e3ccc72469"
E2V_ID="iic/emotion2vec_base"; E2V_REV="v2.0.4"
FUNASR_REV="4a84879ae8ca4d2430953b11c49d609217d93988"
XLSR_ID="facebook/wav2vec2-xls-r-300m"
XLSR_REV="1a640f32ac3e39899438a2931f9924c02f080a54"
INPUT=Path("/kaggle/input")
OUT=Path("/kaggle/working/rs_defhs_system_implementation_001")
VB_B64=""
VA_B64=""

def sha256(p):
    h=hashlib.sha256()
    with open(p,"rb") as f:
        for b in iter(lambda:f.read(1<<20),b""): h.update(b)
    return h.hexdigest()

def dump(p,x):
    Path(p).write_text(json.dumps(x,indent=2,ensure_ascii=False),encoding="utf-8")

def install():
    req=[
      "modelscope==1.40.1","transformers==4.57.1","scikit-learn==1.7.2",
      "h5py==3.14.0","librosa==0.11.0","soundfile==0.13.1",
      "git+https://github.com/modelscope/FunASR.git@"+FUNASR_REV,
    ]
    subprocess.check_call([sys.executable,"-m","pip","install","--quiet","--no-cache-dir",*req])

def deterministic():
    os.environ["PYTHONHASHSEED"]=str(SEED)
    random.seed(SEED)
    import numpy as np, torch
    np.random.seed(SEED); torch.manual_seed(SEED); torch.cuda.manual_seed_all(SEED)
    torch.backends.cudnn.benchmark=False; torch.backends.cudnn.deterministic=True

def embedded(name,b64,expected):
    p=OUT/name; p.write_bytes(base64.b64decode(b64))
    if sha256(p)!=expected: raise RuntimeError(name+" embedded authority hash mismatch")
    return p

def locate_unique(name):
    hits=[p for p in INPUT.rglob(name) if p.is_file()]
    good=[p for p in hits if sha256(p)==MANIFEST_SHA] if name=="DATA_MANIFEST.csv" else hits
    if len(good)!=1: raise RuntimeError(f"Expected one canonical {name}; got {good[:8]}")
    return good[0]

def audio_root():
    roots=[]
    for p in INPUT.rglob("train.csv"):
        b=p.parent
        if (b/"train").is_dir() and (b/"test").is_dir(): roots.append(b)
        if (b/"SRCASW-BhavVaani"/"train").is_dir(): roots.append(b/"SRCASW-BhavVaani")
    roots=list(dict.fromkeys(roots))
    if len(roots)!=1: raise RuntimeError(f"Expected one competition audio root; got {roots}")
    return roots[0]

def audio_path(root,split,fn):
    for p in (root/split/fn,root/fn):
        if p.is_file(): return p
    h=list((root/split).rglob(fn))
    if len(h)==1:return h[0]
    raise FileNotFoundError(f"{split}/{fn}")

def validate(vbp,vap,dmp):
    import pandas as pd
    vb=pd.read_csv(vbp); va=pd.read_csv(vap); dm=pd.read_csv(dmp)
    if len(vb)!=826 or len(va)!=826 or vb.Id.nunique()!=826 or va.Id.nunique()!=826: raise RuntimeError("fold cardinality")
    if set(vb.Id)!=set(va.Id) or set(vb.fold)!={0,1,2,3,4} or set(va.fold)!={0,1,2,3,4}: raise RuntimeError("fold authority")
    if int(vb.groupby("duplicate_group").fold.nunique().max())!=1: raise RuntimeError("V-B duplicate family leakage")
    if len(dm[dm.split=="train"])!=826 or len(dm[dm.split=="test"])!=209: raise RuntimeError("manifest cardinality")
    return vb.sort_values("Id").reset_index(drop=True),va.sort_values("Id").reset_index(drop=True),dm

def read16k(path):
    import numpy as np, soundfile as sf, librosa
    x,sr=sf.read(path,dtype="float32",always_2d=False)
    if x.ndim==2:x=x.mean(1)
    if sr!=16000:x=librosa.resample(x,orig_sr=sr,target_sr=16000,res_type="soxr_hq")
    x=np.asarray(x,dtype=np.float32)
    if x.size==0 or not np.isfinite(x).all(): raise RuntimeError("invalid waveform "+str(path))
    return x

def pool(fr):
    import numpy as np
    z=np.asarray(fr,dtype=np.float32)
    if z.ndim!=2 or z.shape[0]==0 or not np.isfinite(z).all(): raise RuntimeError("bad frames")
    return np.concatenate((z.mean(0),z.std(0))).astype(np.float32)

def hash_tree(root):
    return [{"path":str(p.relative_to(root)),"bytes":p.stat().st_size,"sha256":sha256(p)}
            for p in sorted(root.rglob("*")) if p.is_file()]

def make_e2v(device):
    from funasr import AutoModel
    m=AutoModel(model=E2V_ID,model_revision=E2V_REV,hub="ms",device=device)
    root=Path(m.model_path)
    if not root.exists(): raise RuntimeError("ModelScope resolved path missing")
    return m,root

def e2v_frames(m,p):
    r=m.generate(input=str(p),granularity="frame",extract_embedding=True)
    if isinstance(r,tuple):r=r[0]
    if not isinstance(r,list) or not r or "feats" not in r[0]: raise RuntimeError("emotion2vec output schema")
    return r[0]["feats"]

def make_xlsr(device):
    from transformers import AutoFeatureExtractor,AutoModel
    fe=AutoFeatureExtractor.from_pretrained(XLSR_ID,revision=XLSR_REV,trust_remote_code=False)
    if int(fe.sampling_rate)!=16000 or not bool(fe.do_normalize) or not bool(fe.return_attention_mask):
        raise RuntimeError("XLS-R feature extractor authority mismatch")
    m=AutoModel.from_pretrained(XLSR_ID,revision=XLSR_REV,trust_remote_code=False).to(device).eval()
    return fe,m

def xlsr_frames(fe,m,x,device):
    import torch
    z=fe(x,sampling_rate=16000,return_tensors="pt",return_attention_mask=True)
    z={k:v.to(device) for k,v in z.items()}
    with torch.inference_mode(): y=m(**z).last_hidden_state
    return y[0].detach().cpu().float().numpy()

def parity(name,ids,recs,extract,tol=2e-5):
    import numpy as np
    ds=[]
    for rid in ids:
        a=pool(extract(recs[int(rid)])); b=pool(extract(recs[int(rid)]))
        ds.append(float(np.max(np.abs(a-b))))
    mx=max(ds)
    if mx>tol: raise RuntimeError(f"{name} parity {mx}>{tol}")
    return {"ids":[int(x) for x in ids],"per_id_max_abs":ds,"max_abs":mx,"tolerance":tol}

def extract_all(name,recs,extract):
    import h5py, numpy as np
    h5p=OUT/f"{name}_frames.h5"; ids=[]; X=[]
    with h5py.File(h5p,"w") as h:
        for n,rid in enumerate(sorted(recs)):
            fr=np.asarray(extract(recs[rid]),dtype=np.float32)
            h.create_dataset(str(rid),data=fr,compression="gzip",compression_opts=1,shuffle=True)
            ids.append(rid); X.append(pool(fr))
            if (n+1)%100==0: print(f"{name} {n+1}/{len(recs)}",flush=True)
    npz=OUT/f"{name}_meanstd.npz"; np.savez_compressed(npz,Id=np.asarray(ids),X=np.stack(X))
    return {"frames_h5":h5p.name,"frames_sha256":sha256(h5p),"meanstd_npz":npz.name,"meanstd_sha256":sha256(npz),"shape":list(np.stack(X).shape)}

def evaluate(family,npz,folds,view):
    import numpy as np, pandas as pd
    from sklearn.calibration import CalibratedClassifierCV
    from sklearn.linear_model import LogisticRegression
    from sklearn.metrics import f1_score,confusion_matrix
    from sklearn.model_selection import StratifiedKFold,StratifiedGroupKFold
    from sklearn.pipeline import make_pipeline
    from sklearn.preprocessing import StandardScaler
    from sklearn.svm import SVC
    z=np.load(npz); allid=z["Id"].astype(int); X=z["X"].astype("float32")
    pos={v:i for i,v in enumerate(allid)}
    f=folds.sort_values("Id").reset_index(drop=True); X=X[[pos[int(i)] for i in f.Id]]
    y=f.emotion.to_numpy(); grp=f.duplicate_group.astype(str).to_numpy() if "duplicate_group" in f else None
    out=[]; M={}
    for head in ("L2_LOGREG","RBF_SVM_CAL"):
        P=np.zeros((len(f),4)); pred=np.empty(len(f),object); fs=[]
        for fold in range(5):
            va=np.flatnonzero(f.fold.to_numpy()==fold); tr=np.flatnonzero(f.fold.to_numpy()!=fold)
            if head=="L2_LOGREG":
                clf=make_pipeline(StandardScaler(),LogisticRegression(C=1,max_iter=5000,random_state=SEED))
            else:
                base=make_pipeline(StandardScaler(),SVC(C=10,kernel="rbf",gamma="scale",probability=False,random_state=SEED))
                if grp is not None: cv=list(StratifiedGroupKFold(3,shuffle=True,random_state=SEED+fold).split(X[tr],y[tr],grp[tr]))
                else: cv=list(StratifiedKFold(3,shuffle=True,random_state=SEED+fold).split(X[tr],y[tr]))
                clf=CalibratedClassifierCV(estimator=base,method="sigmoid",cv=cv)
            clf.fit(X[tr],y[tr]); q=clf.predict_proba(X[va]); ci={c:i for i,c in enumerate(clf.classes_)}
            q=np.stack([q[:,ci[c]] for c in CLASSES],1); P[va]=q
            pred[va]=np.asarray(CLASSES,dtype=object)[q.argmax(1)]
            fs.append(float(f1_score(y[va],pred[va],average="macro")))
        M[head]={"macro_f1":float(f1_score(y,pred,average="macro")),"fold_macro_f1":fs,
                 "per_class_f1":{c:float(f1_score(y==c,pred==c)) for c in CLASSES},
                 "confusion":confusion_matrix(y,pred,labels=CLASSES).tolist()}
        for i,rid in enumerate(f.Id):
            r={"Id":int(rid),"emotion":y[i],"family":family,"head":head,"validation":view,"fold":int(f.fold.iloc[i]),"pred":pred[i]}
            r.update({f"p_{c}":float(P[i,j]) for j,c in enumerate(CLASSES)}); out.append(r)
    pd.DataFrame(out).to_csv(OUT/f"OOF_{family}_{view}.csv",index=False)
    return M

def main():
    OUT.mkdir(parents=True,exist_ok=True); install(); deterministic()
    import torch, importlib.metadata as md
    if not torch.cuda.is_available(): raise RuntimeError("GPU required")
    device="cuda:0"
    vbp=embedded("VALIDATION_VB_FOLDS.csv",VB_B64,VB_SHA); vap=embedded("VALIDATION_VA_FOLDS.csv",VA_B64,VA_SHA)
    dmp=locate_unique("DATA_MANIFEST.csv"); vb,va,dm=validate(vbp,vap,dmp); root=audio_root()
    recs={int(r.Id):{"path":audio_path(root,str(r.split),str(r.filename))} for r in dm.itertuples(index=False)}
    dump(OUT/"STAGE1_INPUT_AUTHORITY.json",{"mission":MISSION,"VB":sha256(vbp),"VA":sha256(vap),"DATA_MANIFEST":sha256(dmp),
         "protected_validation_queried":False,"kaggle_submission_made":False})
    (OUT/"ENVIRONMENT_VERSIONS.txt").write_text("\n".join(f"{p}={md.version(p)}" for p in ["torch","numpy","pandas","scikit-learn","transformers","modelscope","funasr","h5py","librosa","soundfile"])+"\n")
    ids=vb.Id.iloc[:3].astype(int).tolist()
    e2v,e2root=make_e2v(device)
    dump(OUT/"E2V_MODELSCOPE_RESOLVED_OBJECT.json",{"model_id":E2V_ID,"revision":E2V_REV,"root":str(e2root),"files":hash_tree(e2root)})
    e2=lambda r:e2v_frames(e2v,r["path"])
    ep=parity("emotion2vec_base",ids,recs,e2); ea=extract_all("emotion2vec_base",recs,e2)
    del e2v; torch.cuda.empty_cache()
    fe,xm=make_xlsr(device)
    xx=lambda r:xlsr_frames(fe,xm,read16k(r["path"]),device)
    xp=parity("xls_r_300m",ids,recs,xx); xa=extract_all("xls_r_300m",recs,xx)
    del xm; torch.cuda.empty_cache()
    dump(OUT/"STAGE1_SMOKE_RESULTS.json",{"status":"PASS","parity":{"emotion2vec_base":ep,"xls_r_300m":xp},
         "artifacts":{"emotion2vec_base":ea,"xls_r_300m":xa},"protected_validation_queried":False,"kaggle_submission_made":False})
    R={}
    for fam in ("emotion2vec_base","xls_r_300m"):
        npz=OUT/f"{fam}_meanstd.npz"; R[fam]={"VB":evaluate(fam,npz,vb,"VB"),"VA":evaluate(fam,npz,va,"VA")}
    dump(OUT/"FROZEN_SCREEN_RESULTS.json",R)
    files=[{"name":p.name,"bytes":p.stat().st_size,"sha256":sha256(p)} for p in sorted(OUT.iterdir()) if p.is_file()]
    dump(OUT/"OUTPUT_INVENTORY.json",{"mission":MISSION,"files":files,"protected_validation_queried":False,"kaggle_submission_made":False})
    print(json.dumps(R,indent=2),flush=True)
    print("RS_DEFHS_FROZEN_SCREEN=SUCCESS",flush=True)
    print("PROTECTED_VALIDATION_NOT_QUERIED=TRUE",flush=True)
    print("KAGGLE_SUBMISSION_NOT_MADE=TRUE",flush=True)

if __name__=="__main__": main()
